import React from "react";

function DashboardPage() {
  return (
    <div style={{ padding: 20 }}>
      <h2>Admin Dashboard</h2>

      <div className="card" style={{ marginTop: 20 }}>
        <h3>Total Users</h3>
        <p>120+</p>
      </div>

      <div className="card" style={{ marginTop: 20 }}>
        <h3>Active Chats</h3>
        <p>45</p>
      </div>
    </div>
  );
}

export default DashboardPage;
